CREATE TABLE `presentation_simulations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `share_token_hash` binary(32) NOT NULL,
  `title` varchar(255) NOT NULL,
  `presentation_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`presentation_data`)),
  `active_slide` smallint(5) unsigned NOT NULL DEFAULT 0,
  `status` enum('active','ended') NOT NULL DEFAULT 'active',
  `expires_at` datetime NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `reveal_mode` enum('all','group','item','timed') NOT NULL DEFAULT 'all',
  `reveal_step` smallint(5) unsigned NOT NULL DEFAULT 0,
  `reveal_interval_seconds` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `annotation_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`annotation_data`)),
  `pointer_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`pointer_data`)),
  `timer_ends_at` datetime DEFAULT NULL,
